<script lang="ts">
 import {onDestroy,onMount} from 'svelte';
 import {ArrowLeft,FolderOpen,Download,LoaderCircle,Check,X,Code2} from 'lucide-svelte';
 import Modal from './Modal.svelte';import PlatformIcon from './PlatformIcon.svelte';
 import {api,readablePath,type Discovery,type ImportSource} from './api';
 let {initial=null,defaultFolder=null,onclose,onimported}:{initial?:Discovery|null;defaultFolder?:string|null;onclose:()=>void;onimported:(count:number)=>void}=$props();
 let result=$state<Discovery|null>(null),busy=$state(false),loading=$state(false),error=$state(''),selected=$state<string[]>([]),title=$state('Import from'),sequence=0,alive=true,addedTotal=0;let failures=$state<{path:string;message:string}[]>([]);
 onMount(()=>{if(initial){result=initial;selected=initial.items.map(r=>r.path);title='Discovered repositories';}});
 onDestroy(()=>{alive=false;++sequence;});
 async function find(source:ImportSource){const request=++sequence;loading=true;error='';result=null;title=source==='github_desktop'?'GitHub Desktop':source==='vs_code'?'Visual Studio Code':'Repository folder';try{let folder:string|null=null;if(source==='folder'){folder=await api.pickRepoFolder('parent');if(folder===null){loading=false;title='Import from';return;}}const value=await api.discover(source,folder);if(alive&&request===sequence){result=value;selected=value.items.map(r=>r.path);}}catch(e){if(alive&&request===sequence)error=String(e);}finally{if(alive&&request===sequence)loading=false;}}
 async function importSelected(){if(busy||!selected.length)return;busy=true;error='';try{const value=await api.importRepositories(selected);if(!alive)return;addedTotal+=value.added;failures=value.failures??[];if(value.remaining.length){selected=value.remaining;error=`Added ${value.added}. ${value.remaining.length} could not be added; review their folders and try again.`;if(result)result={...result,items:result.items.filter(r=>value.remaining.includes(r.path))};}else onimported(addedTotal);}catch(e){if(alive)error=String(e);}finally{busy=false;}}
 function toggle(path:string){selected=selected.includes(path)?selected.filter(p=>p!==path):[...selected,path];}
</script>
<Modal label="Import repositories" canClose={!busy&&!loading} {onclose}>
 <div class="modal-top"><div>{#if result||error}<button class="text-action add-back" disabled={busy||loading} onclick={()=>{result=null;error='';failures=[];title='Import from';}}><ArrowLeft size={14}/> Back</button>{/if}<h2>{title}</h2></div><button class="top-icon" aria-label="Close dialog" disabled={busy||loading} onclick={onclose}><X size={18}/></button></div>
 {#if error}<p class="connection-error" role="alert">{error}</p>{/if}{#each failures as failure}<p class="connection-error import-failure"><strong>{readablePath(failure.path)}</strong><br/>{failure.message}</p>{/each}
 {#if loading}<p class="import-loading" role="status"><LoaderCircle class="spin" size={20}/> Finding repositories…</p>
 {:else if result}
  {#if result.items.length}<label class="scope-choice"><input type="checkbox" checked={selected.length===result.items.length} disabled={busy} onchange={()=>selected=selected.length===result!.items.length?[]:result!.items.map(r=>r.path)}/><span>Select all · {result.items.length} repositories</span></label><div class="import-results">{#each result.items as repo (repo.path)}<label class="import-repository"><input type="checkbox" checked={selected.includes(repo.path)} disabled={busy} onchange={()=>toggle(repo.path)}/><span><strong>{repo.name}</strong><small>{readablePath(repo.path)}</small><small>{repo.source}</small></span></label>{/each}</div>{:else}<p class="empty-small">No new repositories found. Already added repositories are not listed.</p>{/if}
  {#each result.notes as note}<p class="folder-help">{note}</p>{/each}{#if result.limited}<p class="folder-help">Some folders were skipped or the scan limit was reached. Scan a smaller folder for more results.</p>{/if}
  <div class="modal-actions"><button class="secondary" disabled={busy} onclick={onclose}>Cancel</button><button class="primary" disabled={busy||!selected.length} onclick={importSelected}>{#if busy}<LoaderCircle class="spin" size={15}/>{:else}<Download size={15}/>{/if} Import {selected.length} repositories</button></div>
 {:else}
  <div class="add-choices"><button onclick={()=>find('github_desktop')}><span><PlatformIcon remote="https://github.com" size={23}/></span><div><strong>GitHub Desktop</strong><small>Find recorded paths and scan your saved folder.</small></div></button><button onclick={()=>find('vs_code')}><span><Code2 size={23}/></span><div><strong>Visual Studio Code</strong><small>Find recent local Git folders.</small></div></button>{#if defaultFolder}<button onclick={()=>find('default_folder')}><span><Check size={23}/></span><div><strong>Default repository folder</strong><small>Find repositories in your saved folder.</small></div></button>{/if}<button onclick={()=>find('folder')}><span><FolderOpen size={23}/></span><div><strong>Folder · any Git client</strong><small>Choose a folder and review its repositories.</small></div></button></div>
 {/if}
</Modal>
